import { useState } from 'react';
import { useLiveQuery } from 'dexie-react-hooks';
import { db, type ModelConfig } from '@/lib/db';
import { Plus, Trash2, CheckCircle, Key } from 'lucide-react';

const PROVIDERS = [
  { id: 'openai', name: 'OpenAI' },
  { id: 'moonshot', name: 'Moonshot / Kimi' },
  { id: 'custom', name: '自定义 OpenAI 兼容接口' },
  { id: 'anthropic', name: 'Anthropic / Claude' },
  { id: 'google', name: 'Google / Gemini' },
] as const;

export default function Settings() {
  const configs = useLiveQuery(() => db.modelConfigs.toArray());
  const [isAdding, setIsAdding] = useState(false);
  const [testToken, setTestToken] = useState(() => window.localStorage.getItem('fenge_assistant_test_token') || '');
  const [tokenSaved, setTokenSaved] = useState(false);
  const [formData, setFormData] = useState<Partial<ModelConfig>>({
    name: '',
    provider: 'openai',
    apiKey: '',
    baseURL: '',
    model: 'gpt-4o-mini',
    temperature: 0.7,
    maxTokens: 8192,
    isDefault: false
  });

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.apiKey || !formData.provider || !formData.model) return;

    const id = crypto.randomUUID();

    if (formData.isDefault || configs?.length === 0) {
      const allConfigs = await db.modelConfigs.toArray();
      for (const c of allConfigs) {
        if (c.isDefault) await db.modelConfigs.update(c.id, { isDefault: false });
      }
    }

    await db.modelConfigs.add({
      id,
      name: formData.name,
      provider: formData.provider,
      apiKey: formData.apiKey,
      baseURL: formData.baseURL,
      model: formData.model,
      temperature: formData.temperature || 0.7,
      maxTokens: formData.maxTokens || 8192,
      isDefault: formData.isDefault || configs?.length === 0,
      createdAt: new Date(),
      updatedAt: new Date()
    });

    setIsAdding(false);
    setFormData({
      name: '',
      provider: 'openai',
      apiKey: '',
      baseURL: '',
      model: 'gpt-4o-mini',
      temperature: 0.7,
      maxTokens: 8192,
      isDefault: false
    });
  };

  const handleDelete = async (id: string) => {
    await db.modelConfigs.delete(id);
  };

  const handleSetDefault = async (id: string) => {
    if (!configs) return;
    for (const c of configs) {
      await db.modelConfigs.update(c.id, { isDefault: c.id === id });
    }
  };

  const saveTestToken = () => {
    const value = testToken.trim();
    if (value) {
      window.localStorage.setItem('fenge_assistant_test_token', value);
    } else {
      window.localStorage.removeItem('fenge_assistant_test_token');
    }
    setTokenSaved(true);
    window.setTimeout(() => setTokenSaved(false), 1600);
  };

  return (
    <div className="p-8 h-full overflow-y-auto max-w-4xl mx-auto">
      <div className="mb-8 flex justify-between items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">模型设置</h2>
          <p className="text-slate-500 mt-1">添加大模型 API Key。第一版数据仅保存在当前浏览器本地。</p>
        </div>
        <button
          onClick={() => setIsAdding(!isAdding)}
          className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors"
        >
          <Plus className="w-4 h-4" />
          {isAdding ? '取消添加' : '新增配置'}
        </button>
      </div>

      <div className="bg-blue-50 border border-blue-200 rounded-2xl p-5 mb-8">
        <div className="flex flex-col gap-4 md:flex-row md:items-end">
          <div className="flex-1">
            <h3 className="font-semibold text-slate-900">免费体验模型</h3>
            <p className="text-sm text-slate-600 mt-1">
              当前线上已开放免费体验。这里仍保留授权码入口，方便后续切回内部测试模式。
            </p>
            <label className="block text-sm font-medium text-slate-700 mt-4 mb-1">测试授权码</label>
            <input
              type="password"
              value={testToken}
              onChange={e => setTestToken(e.target.value)}
              placeholder="公开体验模式下可不填写"
              className="w-full px-3 py-2 border border-blue-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <button
            type="button"
            onClick={saveTestToken}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            {tokenSaved ? '已保存' : '保存授权码'}
          </button>
        </div>
      </div>

      {isAdding && (
        <form onSubmit={handleAdd} className="bg-white p-6 rounded-2xl border border-blue-200 shadow-sm mb-8">
          <h3 className="text-lg font-semibold mb-4 text-slate-900">新增模型配置</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">配置名称</label>
              <input
                required
                type="text"
                value={formData.name}
                onChange={e => setFormData({ ...formData, name: e.target.value })}
                placeholder="例如：我的 OpenAI 账号"
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">服务商</label>
              <select
                value={formData.provider}
                onChange={e => setFormData({ ...formData, provider: e.target.value as ModelConfig['provider'] })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                {PROVIDERS.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
              </select>
            </div>
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-slate-700 mb-1">API Key</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Key className="h-4 w-4 text-slate-400" />
                </div>
                <input
                  required
                  type="password"
                  value={formData.apiKey}
                  onChange={e => setFormData({ ...formData, apiKey: e.target.value })}
                  placeholder="sk-..."
                  className="w-full pl-10 pr-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Base URL（可选）</label>
              <input
                type="text"
                value={formData.baseURL}
                onChange={e => setFormData({ ...formData, baseURL: e.target.value })}
                placeholder="https://api.openai.com/v1"
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">模型 ID</label>
              <input
                required
                type="text"
                value={formData.model}
                onChange={e => setFormData({ ...formData, model: e.target.value })}
                placeholder="gpt-4o-mini"
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
          </div>
          <div className="mt-6 flex justify-end gap-3">
            <button
              type="button"
              onClick={() => setIsAdding(false)}
              className="px-4 py-2 border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 transition-colors"
            >
              取消
            </button>
            <button
              type="submit"
              className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
            >
              保存配置
            </button>
          </div>
        </form>
      )}

      <div className="space-y-4">
        {configs?.length === 0 && !isAdding && (
          <div className="text-center py-12 bg-white rounded-2xl border border-slate-200 border-dashed">
            <p className="text-slate-500">暂无模型配置，请先添加一个 API Key。</p>
          </div>
        )}

        {configs?.map(config => (
          <div key={config.id} className={`bg-white p-5 rounded-2xl border transition-all ${config.isDefault ? 'border-blue-500 shadow-md' : 'border-slate-200 shadow-sm'}`}>
            <div className="flex justify-between items-start mb-4">
              <div>
                <div className="flex items-center gap-2">
                  <h3 className="text-lg font-semibold text-slate-900">{config.name}</h3>
                  {config.isDefault && (
                    <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                      <CheckCircle className="w-3 h-3" />
                      当前默认
                    </span>
                  )}
                </div>
                <p className="text-slate-500 text-sm mt-1">Provider: {config.provider.toUpperCase()} | Model: {config.model}</p>
              </div>
              <div className="flex items-center gap-2">
                {!config.isDefault && (
                  <button
                    onClick={() => handleSetDefault(config.id)}
                    className="text-sm px-3 py-1.5 border border-slate-200 rounded-lg text-slate-600 hover:bg-slate-50 hover:text-blue-600 transition-colors"
                  >
                    设为默认
                  </button>
                )}
                <button
                  onClick={() => handleDelete(config.id)}
                  className="text-slate-400 hover:text-red-500 p-2 rounded-lg hover:bg-red-50 transition-colors"
                  title="删除配置"
                >
                  <Trash2 className="w-5 h-5" />
                </button>
              </div>
            </div>
            <div className="flex flex-wrap gap-4 text-sm text-slate-500 bg-slate-50 p-3 rounded-lg">
              <div><span className="font-medium">Temperature:</span> {config.temperature}</div>
              <div><span className="font-medium">Max Tokens:</span> {config.maxTokens}</div>
              {config.baseURL && <div className="truncate"><span className="font-medium">Base URL:</span> {config.baseURL}</div>}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
