import { useLiveQuery } from 'dexie-react-hooks';
import { db, type Memory as MemoryItem } from '@/lib/db';
import { useState } from 'react';
import { Plus, Search, Trash2 } from 'lucide-react';

export default function Memory() {
  const memories = useLiveQuery(() => db.memories.orderBy('updatedAt').reverse().toArray());
  const [query, setQuery] = useState('');
  const [form, setForm] = useState({
    title: '',
    content: '',
    tags: '',
    category: 'knowledge' as MemoryItem['category'],
    importance: 2 as MemoryItem['importance']
  });

  const filtered = (memories || []).filter(item => {
    const text = `${item.title} ${item.content} ${item.tags.join(' ')}`;
    return text.toLowerCase().includes(query.toLowerCase());
  });

  const addMemory = async () => {
    if (!form.title.trim() || !form.content.trim()) return;
    await db.memories.add({
      id: crypto.randomUUID(),
      title: form.title.trim(),
      content: form.content.trim(),
      tags: form.tags.split(/[、,，\s]+/).map(tag => tag.trim()).filter(Boolean),
      category: form.category,
      importance: form.importance,
      createdAt: new Date(),
      updatedAt: new Date()
    });
    setForm({ title: '', content: '', tags: '', category: 'knowledge', importance: 2 });
  };

  return (
    <div className="p-8 h-full overflow-y-auto">
      <div className="mb-6">
        <h2 className="text-2xl font-bold text-slate-900">创作记忆</h2>
        <p className="text-slate-500 mt-1">沉淀你的经历、观点、产品资料和案例，后续会自动参与创作上下文。</p>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-[380px_1fr] gap-6">
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 space-y-4">
          <h3 className="font-semibold text-slate-900">添加记忆</h3>
          <input value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="标题" className="w-full rounded-xl border border-slate-200 px-3 py-2" />
          <textarea value={form.content} onChange={e => setForm({ ...form, content: e.target.value })} placeholder="写下这条记忆的具体内容" rows={6} className="w-full rounded-xl border border-slate-200 px-3 py-2" />
          <input value={form.tags} onChange={e => setForm({ ...form, tags: e.target.value })} placeholder="标签，用逗号或顿号分隔" className="w-full rounded-xl border border-slate-200 px-3 py-2" />
          <div className="grid grid-cols-2 gap-3">
            <select value={form.category} onChange={e => setForm({ ...form, category: e.target.value as MemoryItem['category'] })} className="rounded-xl border border-slate-200 px-3 py-2">
              <option value="knowledge">知识</option>
              <option value="work">工作</option>
              <option value="personal">个人</option>
            </select>
            <select value={form.importance} onChange={e => setForm({ ...form, importance: Number(e.target.value) as MemoryItem['importance'] })} className="rounded-xl border border-slate-200 px-3 py-2">
              <option value={1}>普通</option>
              <option value={2}>重要</option>
              <option value={3}>核心</option>
            </select>
          </div>
          <button onClick={addMemory} className="inline-flex w-full items-center justify-center gap-2 rounded-xl bg-blue-600 px-4 py-3 font-semibold text-white hover:bg-blue-700">
            <Plus className="h-4 w-4" />
            保存记忆
          </button>
        </div>

        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
          <div className="relative mb-4">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
            <input value={query} onChange={e => setQuery(e.target.value)} placeholder="搜索记忆" className="w-full rounded-xl border border-slate-200 py-2 pl-9 pr-3" />
          </div>
          <div className="space-y-3">
            {filtered.length ? filtered.map(item => (
              <article key={item.id} className="rounded-xl border border-slate-200 p-4">
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <h3 className="font-semibold text-slate-900">{item.title}</h3>
                    <p className="mt-2 text-sm leading-6 text-slate-600 whitespace-pre-wrap">{item.content}</p>
                  </div>
                  <button onClick={() => db.memories.delete(item.id)} className="text-slate-400 hover:text-red-500">
                    <Trash2 className="h-4 w-4" />
                  </button>
                </div>
                {item.tags.length ? <div className="mt-3 flex flex-wrap gap-2">{item.tags.map(tag => <span key={tag} className="rounded-full bg-slate-100 px-2 py-1 text-xs text-slate-500">{tag}</span>)}</div> : null}
              </article>
            )) : <p className="py-10 text-center text-slate-400">暂无记忆</p>}
          </div>
        </div>
      </div>
    </div>
  );
}
