import { useLiveQuery } from 'dexie-react-hooks';
import { db, initDefaultProfile } from '@/lib/db';
import { buildUserSkillMarkdown } from '@/lib/skillPrompt';
import { useEffect, useMemo, useState } from 'react';
import { ClipboardCopy, Save, Sparkles } from 'lucide-react';

const splitList = (value: string) => value.split(/[、,，\n]+/).map(item => item.trim()).filter(Boolean);

export default function Profile() {
  const profile = useLiveQuery(() => db.profiles.get('default'));
  const memories = useLiveQuery(() => db.memories.orderBy('importance').reverse().limit(8).toArray());
  const [saved, setSaved] = useState(false);
  const [copied, setCopied] = useState(false);
  const [form, setForm] = useState({
    nickname: '',
    profession: '',
    positioning: '',
    expertise: '',
    targetAudience: '',
    contentTopics: '',
    platforms: '公众号',
    writingStyle: '',
    voiceTraits: '',
    personalStories: '',
    contentGoals: '',
    avoidList: '',
    workflowMode: 'quick' as 'quick' | 'system',
    answerStyle: 'formal' as 'formal' | 'casual',
    answerLength: 'medium' as 'short' | 'medium' | 'long',
    professionalism: 7
  });

  useEffect(() => {
    initDefaultProfile();
  }, []);

  useEffect(() => {
    if (!profile) return;
    setForm({
      nickname: profile.nickname,
      profession: profile.profession,
      positioning: profile.positioning || '',
      expertise: profile.expertise.join('、'),
      targetAudience: profile.targetAudience || '',
      contentTopics: (profile.contentTopics || []).join('、'),
      platforms: (profile.platforms || ['公众号']).join('、'),
      writingStyle: profile.writingStyle,
      voiceTraits: profile.voiceTraits || '',
      personalStories: profile.personalStories || '',
      contentGoals: profile.contentGoals || '',
      avoidList: profile.avoidList || '',
      workflowMode: profile.workflowMode || 'quick',
      answerStyle: profile.answerStyle,
      answerLength: profile.answerLength,
      professionalism: profile.professionalism
    });
  }, [profile]);

  const previewProfile = useMemo(() => ({
    id: 'default',
    nickname: form.nickname || '创作者',
    profession: form.profession || '内容创作者',
    expertise: splitList(form.expertise),
    positioning: form.positioning,
    targetAudience: form.targetAudience,
    contentTopics: splitList(form.contentTopics),
    platforms: splitList(form.platforms),
    writingStyle: form.writingStyle || '自然、具体、有行动感',
    voiceTraits: form.voiceTraits,
    personalStories: form.personalStories,
    contentGoals: form.contentGoals,
    avoidList: form.avoidList,
    workflowMode: form.workflowMode,
    answerStyle: form.answerStyle,
    answerLength: form.answerLength,
    professionalism: Number(form.professionalism),
    createdAt: profile?.createdAt || new Date(),
    updatedAt: new Date()
  }), [form, profile?.createdAt]);

  const skillMarkdown = useMemo(
    () => buildUserSkillMarkdown(previewProfile, memories || []),
    [previewProfile, memories]
  );

  const save = async () => {
    await db.profiles.put(previewProfile);
    setSaved(true);
    window.setTimeout(() => setSaved(false), 1600);
  };

  const copySkill = async () => {
    await navigator.clipboard.writeText(skillMarkdown);
    setCopied(true);
    window.setTimeout(() => setCopied(false), 1500);
  };

  return (
    <div className="h-full overflow-y-auto p-8">
      <div className="mb-6 flex flex-col gap-3 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">我的专属 Skill</h2>
          <p className="mt-1 text-slate-500">把身份、风格、读者和创作偏好固化成一个可复用的个人 AI 创作助手。</p>
        </div>
        <div className="flex flex-wrap gap-3">
          <button onClick={copySkill} className="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-semibold text-slate-700 hover:bg-slate-50">
            <ClipboardCopy className="h-4 w-4" />
            {copied ? '已复制 Skill' : '复制 Skill'}
          </button>
          <button onClick={save} className="inline-flex items-center gap-2 rounded-xl bg-blue-600 px-5 py-3 text-sm font-semibold text-white hover:bg-blue-700">
            <Save className="h-4 w-4" />
            {saved ? '已保存' : '保存档案'}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-6 xl:grid-cols-[1fr_420px]">
        <section className="space-y-5">
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 space-y-5">
            <div className="flex items-center gap-2">
              <Sparkles className="h-5 w-5 text-blue-600" />
              <h3 className="font-semibold text-slate-900">用户画像</h3>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <Field label="昵称" value={form.nickname} onChange={value => setForm({ ...form, nickname: value })} />
              <Field label="职业身份" value={form.profession} onChange={value => setForm({ ...form, profession: value })} />
            </div>
            <Area label="个人定位" value={form.positioning} onChange={value => setForm({ ...form, positioning: value })} rows={3} placeholder="例如：用医生式诊断和 AI 实操方法，帮助普通人拿回创作完成权。" />
            <Field label="擅长领域" value={form.expertise} onChange={value => setForm({ ...form, expertise: value })} placeholder="AI编程、提示词、医生、内容创作" />
            <Area label="核心读者" value={form.targetAudience} onChange={value => setForm({ ...form, targetAudience: value })} rows={3} placeholder="例如：40 岁以上想用 AI 提效、写作、做个人 IP 的非技术人。" />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <Field label="内容方向" value={form.contentTopics} onChange={value => setForm({ ...form, contentTopics: value })} placeholder="AI实操、个人成长、内容创作" />
              <Field label="主要平台" value={form.platforms} onChange={value => setForm({ ...form, platforms: value })} placeholder="公众号、小红书、朋友圈、视频号" />
            </div>
          </div>

          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 space-y-5">
            <h3 className="font-semibold text-slate-900">表达与工作流</h3>
            <Area label="写作风格" value={form.writingStyle} onChange={value => setForm({ ...form, writingStyle: value })} rows={4} placeholder="自然、具体、有行动感，短句，少空话。" />
            <Area label="声音特征" value={form.voiceTraits} onChange={value => setForm({ ...form, voiceTraits: value })} rows={4} placeholder="常用句式、语气、节奏、喜欢的隐喻、不要碰的表达。" />
            <Area label="个人经历与素材" value={form.personalStories} onChange={value => setForm({ ...form, personalStories: value })} rows={5} placeholder="写下可以反复调用的经历、转折、踩坑、案例。缺少时，助手会提醒补充。" />
            <Area label="创作目标" value={form.contentGoals} onChange={value => setForm({ ...form, contentGoals: value })} rows={3} placeholder="建立信任、引导咨询、课程转化、社群互动等。" />
            <Area label="禁忌清单" value={form.avoidList} onChange={value => setForm({ ...form, avoidList: value })} rows={3} placeholder="不要夸张承诺，不要标题党，不要鸡汤，不要假数据。" />

            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <Select label="创作流程" value={form.workflowMode} onChange={value => setForm({ ...form, workflowMode: value as 'quick' | 'system' })} options={[['quick', '快写优先'], ['system', '系统流程']]} />
              <Select label="回答风格" value={form.answerStyle} onChange={value => setForm({ ...form, answerStyle: value as 'formal' | 'casual' })} options={[['formal', '正式专业'], ['casual', '轻松直接']]} />
              <Select label="回答长度" value={form.answerLength} onChange={value => setForm({ ...form, answerLength: value as 'short' | 'medium' | 'long' })} options={[['short', '简短'], ['medium', '适中'], ['long', '详细']]} />
              <label className="block">
                <span className="text-sm font-medium text-slate-700">专业程度：{form.professionalism}</span>
                <input
                  type="range"
                  min={1}
                  max={10}
                  value={form.professionalism}
                  onChange={event => setForm({ ...form, professionalism: Number(event.target.value) })}
                  className="mt-3 w-full accent-blue-600"
                />
              </label>
            </div>
          </div>
        </section>

        <aside className="bg-slate-950 text-slate-100 rounded-2xl border border-slate-800 p-5 shadow-sm xl:sticky xl:top-8 self-start">
          <div className="mb-4 flex items-center justify-between gap-3">
            <div>
              <h3 className="font-semibold">实时 Skill 预览</h3>
              <p className="mt-1 text-xs text-slate-400">写作和对话会调用这份内容。</p>
            </div>
          </div>
          <pre className="max-h-[720px] overflow-auto whitespace-pre-wrap rounded-xl bg-slate-900 p-4 text-xs leading-6 text-slate-200">{skillMarkdown}</pre>
        </aside>
      </div>
    </div>
  );
}

function Field({ label, value, onChange, placeholder = '' }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string }) {
  return (
    <label className="block">
      <span className="text-sm font-medium text-slate-700">{label}</span>
      <input
        value={value}
        onChange={event => onChange(event.target.value)}
        placeholder={placeholder}
        className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
      />
    </label>
  );
}

function Area({ label, value, onChange, rows, placeholder = '' }: { label: string; value: string; onChange: (value: string) => void; rows: number; placeholder?: string }) {
  return (
    <label className="block">
      <span className="text-sm font-medium text-slate-700">{label}</span>
      <textarea
        value={value}
        onChange={event => onChange(event.target.value)}
        rows={rows}
        placeholder={placeholder}
        className="mt-1 w-full resize-y rounded-xl border border-slate-200 px-3 py-2 leading-6 focus:outline-none focus:ring-2 focus:ring-blue-500"
      />
    </label>
  );
}

function Select({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: Array<[string, string]> }) {
  return (
    <label className="block">
      <span className="text-sm font-medium text-slate-700">{label}</span>
      <select
        value={value}
        onChange={event => onChange(event.target.value)}
        className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
      >
        {options.map(([optionValue, labelText]) => <option key={optionValue} value={optionValue}>{labelText}</option>)}
      </select>
    </label>
  );
}
