import { useState, useRef, useEffect } from 'react';
import { useLiveQuery } from 'dexie-react-hooks';
import { db, type ChatHistory, type ChatMessage } from '@/lib/db';
import { chatCompletion } from '@/lib/api';
import { buildAssistantSystemPrompt } from '@/lib/skillPrompt';
import ReactMarkdown from 'react-markdown';
import {
  Send,
  Bot,
  User,
  Trash2,
  ImagePlus,
  Plus,
  MessageSquare,
  ChevronDown,
  ChevronUp
} from 'lucide-react';

const SITE_TEST_CONFIG = {
  id: 'site-test-model',
  name: '免费体验模型',
  provider: 'custom' as const,
  apiKey: '',
  baseURL: '',
  model: 'astron-code-latest',
  temperature: 0.7,
  maxTokens: 8192,
  isDefault: true,
  createdAt: new Date(0),
  updatedAt: new Date(0)
};

const MAX_IMAGES = 3;
const MAX_IMAGE_SIZE_MB = 4;
const MAX_IMAGE_SIZE_BYTES = MAX_IMAGE_SIZE_MB * 1024 * 1024;

export default function Chat() {
  const configs = useLiveQuery(() => db.modelConfigs.toArray());
  const availableConfigs = [SITE_TEST_CONFIG, ...(configs || [])];
  const defaultConfig = SITE_TEST_CONFIG;
  const histories = useLiveQuery(() => db.chatHistories.orderBy('updatedAt').reverse().toArray());
  const profile = useLiveQuery(() => db.profiles.get('default'));
  const memories = useLiveQuery(() => db.memories.orderBy('importance').reverse().limit(8).toArray());

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [activeHistoryId, setActiveHistoryId] = useState<string>('');
  const [input, setInput] = useState('');
  const [images, setImages] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [selectedConfigId, setSelectedConfigId] = useState<string>('');
  const [showScrollButtons, setShowScrollButtons] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messagesScrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (defaultConfig && !selectedConfigId) {
      setSelectedConfigId(defaultConfig.id);
    }
  }, [defaultConfig, selectedConfigId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
  }, [messages]);

  const updateScrollButtons = () => {
    const container = messagesScrollRef.current;
    if (!container) return;
    setShowScrollButtons(container.scrollHeight - container.clientHeight > 24);
  };

  useEffect(() => {
    updateScrollButtons();
  }, [messages]);

  useEffect(() => {
    window.addEventListener('resize', updateScrollButtons);
    return () => window.removeEventListener('resize', updateScrollButtons);
  }, []);

  const scrollMessages = (position: 'top' | 'bottom') => {
    const container = messagesScrollRef.current;
    if (!container) return;
    container.scrollTo({
      top: position === 'top' ? 0 : container.scrollHeight,
      behavior: 'smooth'
    });
  };

  const saveHistory = async (nextMessages: ChatMessage[], historyId = activeHistoryId) => {
    const now = new Date();
    const firstUserMessage = nextMessages.find(m => m.role === 'user')?.content || '新对话';
    const title = firstUserMessage.slice(0, 28);

    if (historyId) {
      await db.chatHistories.update(historyId, {
        title,
        messages: nextMessages,
        modelConfigId: selectedConfigId || 'site-test-model',
        updatedAt: now
      });
      return historyId;
    }

    const id = crypto.randomUUID();
    await db.chatHistories.add({
      id,
      title,
      messages: nextMessages,
      modelConfigId: selectedConfigId || 'site-test-model',
      createdAt: now,
      updatedAt: now
    });
    setActiveHistoryId(id);
    return id;
  };

  const startNewChat = () => {
    setActiveHistoryId('');
    setMessages([]);
    setImages([]);
  };

  const loadHistory = (history: ChatHistory) => {
    setActiveHistoryId(history.id);
    setMessages(history.messages);
    setSelectedConfigId(history.modelConfigId || 'site-test-model');
    setImages([]);
  };

  const deleteHistory = async (id: string) => {
    await db.chatHistories.delete(id);
    if (id === activeHistoryId) startNewChat();
  };

  const handleImageUpload = async (files: FileList | null) => {
    if (!files?.length) return;
    const slotsLeft = MAX_IMAGES - images.length;
    const picked = Array.from(files)
      .filter(file => file.type.startsWith('image/'))
      .slice(0, slotsLeft);

    const oversized = picked.filter(file => file.size > MAX_IMAGE_SIZE_BYTES);
    if (oversized.length > 0) {
      alert(`单张图片不能超过 ${MAX_IMAGE_SIZE_MB}MB，请压缩后再上传。`);
    }

    const validFiles = picked.filter(file => file.size <= MAX_IMAGE_SIZE_BYTES);
    const encoded = await Promise.all(validFiles.map(file => new Promise<string>((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(String(reader.result));
      reader.onerror = reject;
      reader.readAsDataURL(file);
    })));

    setImages(prev => [...prev, ...encoded].slice(0, MAX_IMAGES));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSend = async () => {
    if ((!input.trim() && images.length === 0) || isLoading) return;

    const activeConfig = availableConfigs.find(c => c.id === selectedConfigId);
    if (!activeConfig) {
      alert('请先在“模型设置”中添加并选择一个模型配置。');
      return;
    }

    const newUserMessage: ChatMessage = {
      role: 'user',
      content: input || '请分析这张图片',
      timestamp: new Date(),
      images
    };

    const newMessages = [...messages, newUserMessage];
    setMessages([...newMessages, { role: 'assistant', content: '', timestamp: new Date() }]);
    setInput('');
    setImages([]);
    setIsLoading(true);
    const historyId = await saveHistory(newMessages);

    try {
      let assistantContent = '';
      const requestMessages: ChatMessage[] = [
        { role: 'system', content: buildAssistantSystemPrompt(profile, memories || []), timestamp: new Date() },
        ...newMessages
      ];
      await chatCompletion(requestMessages, activeConfig, chunk => {
        assistantContent += chunk;
        setMessages(prev => {
          const last = prev[prev.length - 1];
          return [
            ...prev.slice(0, -1),
            { ...last, content: last.content + chunk }
          ];
        });
      });
      await saveHistory([...newMessages, { role: 'assistant', content: assistantContent, timestamp: new Date() }], historyId);
    } catch (error: any) {
      const errorMessage = `**请求失败：** ${error.message}`;
      setMessages(prev => {
        const last = prev[prev.length - 1];
        return [
          ...prev.slice(0, -1),
          { ...last, content: errorMessage }
        ];
      });
      await saveHistory([...newMessages, { role: 'assistant', content: errorMessage, timestamp: new Date() }], historyId);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="grid grid-cols-[280px_1fr] h-full min-h-0 bg-slate-50 relative">
      <aside className="border-r border-slate-200 bg-white flex flex-col min-h-0">
        <div className="p-4 border-b border-slate-200">
          <button
            onClick={startNewChat}
            className="w-full flex items-center justify-center gap-2 rounded-xl bg-blue-600 px-4 py-3 text-sm font-semibold text-white hover:bg-blue-700"
          >
            <Plus className="w-4 h-4" />
            新建对话
          </button>
        </div>
        <div className="flex-1 overflow-y-auto p-3 space-y-2">
          {histories?.length ? histories.map(history => (
            <div
              key={history.id}
              className={`group rounded-xl border p-3 cursor-pointer ${
                activeHistoryId === history.id ? 'border-blue-300 bg-blue-50' : 'border-slate-200 hover:bg-slate-50'
              }`}
              onClick={() => loadHistory(history)}
            >
              <div className="flex items-start gap-2">
                <MessageSquare className="w-4 h-4 mt-0.5 text-slate-400 shrink-0" />
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-slate-800 truncate">{history.title}</p>
                  <p className="text-xs text-slate-400 mt-1">{new Date(history.updatedAt).toLocaleString()}</p>
                </div>
                <button
                  onClick={event => {
                    event.stopPropagation();
                    deleteHistory(history.id);
                  }}
                  className="opacity-0 group-hover:opacity-100 text-slate-400 hover:text-red-500"
                  title="删除"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            </div>
          )) : (
            <p className="text-sm text-slate-400 text-center py-8">暂无对话记录</p>
          )}
        </div>
      </aside>

      <section className="flex flex-col min-w-0 min-h-0 h-full">
        <header className="bg-white px-6 py-3 border-b border-slate-200 flex items-center justify-between z-10 shadow-sm">
          <div>
            <h2 className="text-lg font-semibold text-slate-900">AI 对话</h2>
            <p className="text-xs text-slate-500 mt-1">默认使用免费体验模型，支持文字和图片对话。</p>
          </div>
          <div className="flex items-center gap-4">
            <select
              value={selectedConfigId}
              onChange={e => setSelectedConfigId(e.target.value)}
              className="px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="" disabled>选择模型配置...</option>
              {availableConfigs.map(c => (
                <option key={c.id} value={c.id}>{c.name} ({c.model})</option>
              ))}
            </select>
            <button
              onClick={startNewChat}
              className="text-slate-400 hover:text-slate-600 transition-colors"
              title="清空对话"
            >
              <Trash2 className="w-5 h-5" />
            </button>
          </div>
        </header>

        <div className="relative flex-1 min-h-0">
          <div
            ref={messagesScrollRef}
            onScroll={updateScrollButtons}
            className="absolute inset-0 overflow-y-auto p-6 space-y-6 scroll-smooth"
          >
            {messages.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-slate-400">
                <Bot className="w-12 h-12 mb-4 text-slate-300" />
                <p>输入你的问题，开始与专属 Skill 助手对话。</p>
                <p className="text-sm mt-2">它会自动参考你的档案、创作记忆和表达偏好。</p>
              </div>
            ) : (
              messages.map((msg, idx) => (
                <div key={idx} className={`flex gap-4 max-w-4xl mx-auto ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
                  <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${
                    msg.role === 'user' ? 'bg-blue-600 text-white' : 'bg-emerald-500 text-white'
                  }`}>
                    {msg.role === 'user' ? <User className="w-5 h-5" /> : <Bot className="w-5 h-5" />}
                  </div>
                  <div className={`min-w-0 flex-1 px-5 py-4 rounded-2xl ${
                    msg.role === 'user'
                      ? 'bg-blue-600 text-white rounded-tr-none'
                      : 'bg-white border border-slate-200 text-slate-800 rounded-tl-none shadow-sm'
                  }`}>
                    {msg.role === 'assistant' ? (
                      <div className="prose prose-slate max-w-none break-words prose-p:leading-relaxed prose-pre:bg-slate-800 prose-pre:text-slate-50 prose-pre:whitespace-pre-wrap">
                        <ReactMarkdown>{msg.content || '...'}</ReactMarkdown>
                      </div>
                    ) : (
                      <div className="space-y-3">
                        {msg.images?.length ? (
                          <div className="flex flex-wrap gap-2 justify-end">
                            {msg.images.map((image, imageIndex) => (
                              <img key={imageIndex} src={image} alt="上传图片" className="max-h-36 rounded-lg border border-white/30" />
                            ))}
                          </div>
                        ) : null}
                        <div className="whitespace-pre-wrap break-words">{msg.content}</div>
                      </div>
                    )}
                  </div>
                </div>
              ))
            )}
            <div ref={messagesEndRef} />
          </div>

          {showScrollButtons && (
            <div className="absolute right-5 bottom-5 z-20 flex flex-col gap-2">
              <button
                type="button"
                onClick={() => scrollMessages('top')}
                className="h-10 w-10 rounded-full border border-slate-200 bg-white text-slate-600 shadow-lg hover:bg-slate-50"
                title="回到顶部"
              >
                <ChevronUp className="mx-auto h-5 w-5" />
              </button>
              <button
                type="button"
                onClick={() => scrollMessages('bottom')}
                className="h-10 w-10 rounded-full border border-slate-200 bg-white text-slate-600 shadow-lg hover:bg-slate-50"
                title="跳到底部"
              >
                <ChevronDown className="mx-auto h-5 w-5" />
              </button>
            </div>
          )}
        </div>

        <div className="p-4 bg-white border-t border-slate-200">
          {images.length > 0 && (
            <div className="max-w-4xl mx-auto mb-3 flex flex-wrap gap-2">
              {images.map((image, index) => (
                <div key={index} className="relative">
                  <img src={image} alt="待发送图片" className="h-20 w-20 object-cover rounded-lg border border-slate-200" />
                  <button
                    onClick={() => setImages(prev => prev.filter((_, i) => i !== index))}
                    className="absolute -right-2 -top-2 h-6 w-6 rounded-full bg-slate-900 text-white text-xs"
                    title="移除图片"
                  >
                    x
                  </button>
                </div>
              ))}
            </div>
          )}
          <div className="max-w-4xl mx-auto relative flex items-end gap-2">
            <input
              ref={fileInputRef}
              type="file"
              accept="image/*"
              multiple
              className="hidden"
              onChange={event => handleImageUpload(event.target.files)}
            />
            <button
              onClick={() => fileInputRef.current?.click()}
              disabled={images.length >= MAX_IMAGES || isLoading}
              className="h-14 px-4 rounded-xl border border-slate-200 text-slate-500 hover:bg-slate-50 disabled:opacity-50 flex items-center justify-center shrink-0"
              title="上传图片"
            >
              <ImagePlus className="w-5 h-5" />
            </button>
            <textarea
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="输入消息，Enter 发送，Shift + Enter 换行..."
              className="w-full max-h-32 min-h-[56px] resize-y px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white transition-colors"
              rows={1}
            />
            <button
              onClick={handleSend}
              disabled={isLoading || (!input.trim() && images.length === 0)}
              className="h-14 px-5 bg-blue-600 text-white rounded-xl hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center justify-center flex-shrink-0"
            >
              <Send className="w-5 h-5" />
            </button>
          </div>
        </div>
      </section>
    </div>
  );
}
