import { type ModelConfig, type ChatMessage } from './db';

function toOpenAIContent(message: ChatMessage) {
  if (!message.images?.length) {
    return message.content;
  }

  return [
    { type: 'text', text: message.content || '请分析这张图片' },
    ...message.images.map(image => ({
      type: 'image_url',
      image_url: { url: image }
    }))
  ];
}

export async function chatCompletion(
  messages: ChatMessage[],
  config: ModelConfig,
  onUpdate: (chunk: string) => void
) {
  if (config.provider === 'custom' && config.id === 'site-test-model') {
    return siteTestChatCompletion(messages, onUpdate);
  }

  let url = 'https://api.openai.com/v1/chat/completions';

  if (config.baseURL) {
    url = config.baseURL.endsWith('/')
      ? `${config.baseURL}chat/completions`
      : `${config.baseURL}/chat/completions`;
  }

  if (!config.baseURL) {
    switch (config.provider) {
      case 'moonshot':
        url = 'https://api.moonshot.cn/v1/chat/completions';
        break;
      case 'anthropic':
        throw new Error('Anthropic 直连需要不同接口格式。请使用兼容 OpenAI 格式的代理服务，或填写自定义 Base URL。');
      case 'google':
        throw new Error('Google Gemini 直连需要不同接口格式。请使用兼容 OpenAI 格式的代理服务，或填写自定义 Base URL。');
      case 'custom':
        throw new Error('使用自定义服务商时，必须提供 Base URL，例如 https://api.example.com/v1。');
      default:
        break;
    }
  }

  let fetchUrl = url;
  if (url.startsWith('http')) {
    fetchUrl = `/api/proxy?target=${encodeURIComponent(url)}`;
  }

  const response = await fetch(fetchUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${config.apiKey}`
    },
    body: JSON.stringify({
      model: config.model,
      messages: messages.map(m => ({ role: m.role, content: toOpenAIContent(m) })),
      temperature: config.temperature,
      max_tokens: Math.max(config.maxTokens || 0, 8192),
      stream: true
    })
  });

  if (!response.ok) {
    let errMsg = `API 请求失败 (${response.status})`;
    try {
      const err = await response.json();
      errMsg = err.error?.message || err.message || JSON.stringify(err) || errMsg;
    } catch {
      try {
        const textErr = await response.text();
        if (textErr) errMsg += `: ${textErr}`;
      } catch {}
    }
    throw new Error(errMsg);
  }

  if (!response.body) throw new Error('接口没有返回可读取的数据流');

  const reader = response.body.getReader();
  const decoder = new TextDecoder('utf-8');
  let done = false;

  while (!done) {
    const { value, done: readerDone } = await reader.read();
    done = readerDone;
    if (!value) continue;

    const chunk = decoder.decode(value, { stream: true });
    const lines = chunk.split('\n').filter(line => line.trim() !== '');

    for (const line of lines) {
      if (!line.startsWith('data: ')) continue;
      const data = line.slice(6);
      if (data === '[DONE]') continue;
      try {
        const parsed = JSON.parse(data);
        const content = parsed.choices?.[0]?.delta?.content || '';
        if (content) onUpdate(content);
      } catch (error) {
        console.error('Failed to parse stream chunk:', error);
      }
    }
  }
}

export async function siteTestChatCompletion(
  messages: ChatMessage[],
  onUpdate: (chunk: string) => void
) {
  const token = window.localStorage.getItem('fenge_assistant_test_token') || '';

  const response = await fetch('/assistant/api/chat', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Assistant-Test-Token': token
    },
    body: JSON.stringify({
      messages: messages.map(m => ({ role: m.role, content: m.content, images: m.images || [] }))
    })
  });

  if (!response.ok) {
    let message = `测试模型请求失败 (${response.status})`;
    try {
      const error = await response.json();
      message = error.error || error.message || message;
    } catch {}
    throw new Error(message);
  }

  if (!response.body) throw new Error('接口没有返回可读取的数据流');

  const reader = response.body.getReader();
  const decoder = new TextDecoder('utf-8');
  let buffer = '';

  while (true) {
    const { value, done } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    const lines = buffer.split('\n');
    buffer = lines.pop() || '';

    for (const line of lines) {
      if (!line.startsWith('data: ')) continue;
      const data = line.slice(6);
      if (data === '[DONE]') return;
      try {
        const parsed = JSON.parse(data);
        if (parsed.error) throw new Error(parsed.error);
        if (parsed.content) onUpdate(parsed.content);
      } catch (error) {
        if (error instanceof Error) throw error;
      }
    }
  }
}
