import Dexie, { type Table } from 'dexie';

export interface UserProfile {
  id: string;
  nickname: string;
  profession: string;
  expertise: string[];
  writingStyle: string;
  positioning?: string;
  targetAudience?: string;
  contentTopics?: string[];
  voiceTraits?: string;
  personalStories?: string;
  contentGoals?: string;
  platforms?: string[];
  avoidList?: string;
  workflowMode?: 'quick' | 'system';
  answerStyle: 'formal' | 'casual';
  answerLength: 'short' | 'medium' | 'long';
  professionalism: number;
  createdAt: Date;
  updatedAt: Date;
}

export interface Memory {
  id: string;
  title: string;
  content: string;
  tags: string[];
  importance: 1 | 2 | 3;
  category: 'personal' | 'work' | 'knowledge';
  createdAt: Date;
  updatedAt: Date;
}

export interface ModelConfig {
  id: string;
  name: string;
  provider: 'openai' | 'anthropic' | 'google' | 'moonshot' | 'custom';
  apiKey: string;
  baseURL?: string;
  model: string;
  temperature: number;
  maxTokens: number;
  isDefault: boolean;
  createdAt: Date;
  updatedAt: Date;
}

export interface ChatMessage {
  role: 'user' | 'assistant' | 'system';
  content: string;
  timestamp: Date;
  images?: string[];
}

export interface ChatHistory {
  id: string;
  title: string;
  modelConfigId: string;
  messages: ChatMessage[];
  createdAt: Date;
  updatedAt: Date;
}

export interface WritingProject {
  id: string;
  title: string;
  topic: string;
  outline: string;
  content: string;
  versions: Array<{
    version: number;
    content: string;
    changes: string;
    createdAt: Date;
  }>;
  status: 'topic' | 'outline' | 'writing' | 'completed';
  createdAt: Date;
  updatedAt: Date;
}

export class AppDatabase extends Dexie {
  profiles!: Table<UserProfile, string>;
  memories!: Table<Memory, string>;
  modelConfigs!: Table<ModelConfig, string>;
  chatHistories!: Table<ChatHistory, string>;
  writingProjects!: Table<WritingProject, string>;

  constructor() {
    super('FengeCreatorAssistantDB');
    this.version(1).stores({
      profiles: 'id',
      memories: 'id, category, importance, *tags',
      modelConfigs: 'id, provider, isDefault',
      chatHistories: 'id, createdAt',
      writingProjects: 'id, status, createdAt'
    });
    this.version(2).stores({
      profiles: 'id, updatedAt',
      memories: 'id, category, importance, updatedAt, createdAt, *tags',
      modelConfigs: 'id, provider, isDefault, updatedAt',
      chatHistories: 'id, createdAt, updatedAt',
      writingProjects: 'id, status, createdAt, updatedAt'
    });
  }
}

export const db = new AppDatabase();

export async function initDefaultProfile() {
  const count = await db.profiles.count();
  if (count === 0) {
    await db.profiles.add({
      id: 'default',
      nickname: '创作者',
      profession: '内容创作者',
      expertise: [],
      writingStyle: '自然、具体、有行动感',
      positioning: '用自己的经历和专业能力，帮助读者把 AI 真正用起来。',
      targetAudience: '想用 AI 提效、创作或做个人 IP，但不知道从哪开始的普通人。',
      contentTopics: ['AI 实操', '个人成长', '内容创作'],
      voiceTraits: '真诚、直接、短句、少空话，多讲真实经历和具体动作。',
      personalStories: '',
      contentGoals: '建立信任，输出实用方法，引导读者采取下一步行动。',
      platforms: ['公众号'],
      avoidList: '不要夸张承诺，不要标题党，不要鸡汤，不要假数据。',
      workflowMode: 'quick',
      answerStyle: 'formal',
      answerLength: 'medium',
      professionalism: 7,
      createdAt: new Date(),
      updatedAt: new Date()
    });
  }
}
