import { useEffect, useState } from 'react';
import { useLiveQuery } from 'dexie-react-hooks';
import { ArrowRight, ClipboardCopy, FileText, Lightbulb, ListChecks, PenLine, RefreshCw, Sparkles } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { db, type ChatMessage } from '@/lib/db';
import { siteTestChatCompletion } from '@/lib/api';
import { buildAssistantSystemPrompt, buildUserSkillMarkdown } from '@/lib/skillPrompt';

const actions = [
  {
    id: 'topic',
    label: '生成选题',
    icon: Lightbulb,
    prompt: '请根据用户的创作需求，生成 8 个适合发布的选题。每个选题要有标题、目标读者、爆点理由。'
  },
  {
    id: 'outline',
    label: '生成大纲',
    icon: ListChecks,
    prompt: '请根据用户的创作需求和已有素材，生成一份公众号文章大纲。要求结构清晰、案例具体、适合继续扩写。'
  },
  {
    id: 'draft',
    label: '生成正文',
    icon: FileText,
    prompt: '请根据用户的创作需求和已有素材，写一篇公众号文章初稿。要求具体、接地气、有行动感，避免空话。'
  },
  {
    id: 'title',
    label: '优化标题',
    icon: PenLine,
    prompt: '请根据用户的创作需求和已有素材，生成 12 个更适合传播的公众号标题，并说明每个标题适合的传播角度。'
  },
  {
    id: 'polish',
    label: '润色成稿',
    icon: Sparkles,
    prompt: '请把已有素材润色成更适合公众号发布的成稿，优化开头、结构、金句和结尾行动号召。'
  }
];

const writingDraftKey = 'fenge_assistant_writing_draft_v1';
const wechatImportKey = 'fenge_wechat_import_markdown';

export default function Writing() {
  const profile = useLiveQuery(() => db.profiles.get('default'));
  const memories = useLiveQuery(() => db.memories.orderBy('importance').reverse().limit(8).toArray());
  const [requirement, setRequirement] = useState('');
  const [material, setMaterial] = useState('');
  const [reply, setReply] = useState('');
  const [loadingAction, setLoadingAction] = useState('');
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    try {
      const saved = window.localStorage.getItem(writingDraftKey);
      if (!saved) return;
      const draft = JSON.parse(saved);
      setRequirement(draft.requirement || '');
      setMaterial(draft.material || '');
      setReply(draft.reply || '');
    } catch {}
  }, []);

  useEffect(() => {
    const draft = {
      requirement,
      material,
      reply,
      updatedAt: new Date().toISOString()
    };
    window.localStorage.setItem(writingDraftKey, JSON.stringify(draft));
  }, [requirement, material, reply]);

  const context = [
    buildAssistantSystemPrompt(profile, memories || []),
    material ? `上一轮素材：\n${material}` : ''
  ].filter(Boolean).join('\n\n');

  const skillPreview = buildUserSkillMarkdown(profile, memories || []);

  const runAction = async (action: typeof actions[number]) => {
    if (!requirement.trim() && !material.trim()) {
      alert('请先输入创作需求，或者把上一轮回复作为下一步素材。');
      return;
    }

    setLoadingAction(action.id);
    setReply('');

    const prompt = [
      '你是枫哥AI进化社的文章创作助手。现在必须采用“用户专属 Skill”方式工作。',
      profile?.workflowMode === 'system'
        ? '用户选择了系统流程：先给角度和骨架；如果用户没有要求直接成稿，先不要跳到完整正文。'
        : '用户选择了快写流程：在信息足够时直接交付可用结果，信息不足时用合理假设补齐。',
      action.prompt,
      `创作需求：\n${requirement || '用户没有补充新的创作需求，请基于已有素材继续。'}`,
      context
    ].filter(Boolean).join('\n\n');

    const messages: ChatMessage[] = [{ role: 'user', content: prompt, timestamp: new Date() }];
    let output = '';

    try {
      await siteTestChatCompletion(messages, chunk => {
        output += chunk;
        setReply(output);
      });
    } catch (error) {
      setReply(error instanceof Error ? `**生成失败：** ${error.message}` : '**生成失败：** 请稍后再试。');
    } finally {
      setLoadingAction('');
    }
  };

  const useAsMaterial = () => {
    if (!reply.trim()) return;
    setMaterial(reply);
  };

  const copyReply = async () => {
    await navigator.clipboard.writeText(reply);
    setCopied(true);
    window.setTimeout(() => setCopied(false), 1500);
  };

  const sendToWechat = () => {
    const markdown = (reply || material || requirement).trim();
    if (!markdown) {
      alert('还没有可传到排版工具的文章内容。请先生成正文，或把正文粘贴到“下一步素材”。');
      return;
    }
    window.localStorage.setItem(wechatImportKey, markdown);
    window.localStorage.setItem(`${wechatImportKey}_time`, new Date().toISOString());
    window.location.href = '/wechat/?from=assistant';
  };

  return (
    <div className="p-8 h-full overflow-y-auto">
      <div className="mb-6">
        <h2 className="text-2xl font-bold text-slate-900">专属 Skill 写作台</h2>
        <p className="text-slate-500 mt-1">这里会自动调用「我的专属 Skill」和创作记忆，再生成选题、大纲、正文和改稿。</p>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-[1fr_360px] gap-6">
        <main className="space-y-5">
          <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-5">
            <div className="mb-3 flex items-center justify-between gap-3">
              <div>
                <h3 className="font-semibold text-slate-900">创作需求</h3>
                <p className="text-sm text-slate-500 mt-1">写主题、目标读者、核心观点、用途和风格要求。</p>
              </div>
              <button
                onClick={() => setRequirement('')}
                className="text-sm text-slate-400 hover:text-slate-600"
              >
                清空
              </button>
            </div>
            <textarea
              value={requirement}
              onChange={event => setRequirement(event.target.value)}
              rows={7}
              placeholder="例如：我想写一篇公众号文章，讲普通人如何用 AI 编程做出自己的第一个小工具。目标读者是 40 岁以上非程序员，风格要接地气、有行动感，最后引导他们加入枫哥AI进化社。"
              className="w-full resize-y rounded-xl border border-slate-200 px-4 py-3 text-sm leading-7 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </section>

          <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-5">
            <h3 className="font-semibold text-slate-900 mb-3">选择下一步</h3>
            <div className="flex flex-wrap gap-3">
              {actions.map(action => {
                const Icon = action.icon;
                return (
                  <button
                    key={action.id}
                    onClick={() => runAction(action)}
                    disabled={Boolean(loadingAction)}
                    className="inline-flex items-center gap-2 rounded-xl bg-blue-600 px-4 py-3 text-sm font-semibold text-white hover:bg-blue-700 disabled:opacity-60"
                  >
                    <Icon className="h-4 w-4" />
                    {loadingAction === action.id ? '生成中...' : action.label}
                  </button>
                );
              })}
            </div>
          </section>

          <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-5 min-h-[360px]">
            <div className="mb-4 flex items-center justify-between gap-3">
              <div>
                <h3 className="font-semibold text-slate-900">AI 回复</h3>
                <p className="text-sm text-slate-500 mt-1">所有生成结果都会集中显示在这里。</p>
              </div>
              <div className="flex flex-wrap gap-2">
                <button
                  onClick={useAsMaterial}
                  disabled={!reply.trim()}
                  className="inline-flex items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-sm font-semibold text-slate-600 hover:bg-slate-50 disabled:opacity-50"
                >
                  <RefreshCw className="h-4 w-4" />
                  作为下一步素材
                </button>
                <button
                  onClick={copyReply}
                  disabled={!reply.trim()}
                  className="inline-flex items-center gap-2 rounded-lg bg-slate-900 px-3 py-2 text-sm font-semibold text-white hover:bg-slate-700 disabled:opacity-50"
                >
                  <ClipboardCopy className="h-4 w-4" />
                  {copied ? '已复制' : '复制'}
                </button>
              </div>
            </div>

            {reply ? (
              <div className="prose prose-slate max-w-none prose-p:leading-7 prose-li:leading-7">
                <ReactMarkdown>{reply}</ReactMarkdown>
              </div>
            ) : (
              <div className="flex min-h-[260px] items-center justify-center rounded-xl border border-dashed border-slate-200 bg-slate-50 text-slate-400">
                输入创作需求后，点击上方按钮开始生成。
              </div>
            )}
          </section>
        </main>

        <aside className="space-y-5">
          <section className="bg-white rounded-2xl border border-slate-200 p-5 shadow-sm">
            <h3 className="font-semibold text-slate-900 mb-2">当前调用</h3>
            <div className="rounded-xl border border-blue-100 bg-blue-50 p-4 text-sm leading-6 text-blue-900">
              <p className="font-semibold">{profile?.nickname || '创作者'}的个人创作 Skill</p>
              <p className="mt-1 text-blue-700">模式：{profile?.workflowMode === 'system' ? '系统流程' : '快写优先'} · 平台：{profile?.platforms?.join('、') || '公众号'}</p>
            </div>
          </section>

          <section className="bg-white rounded-2xl border border-slate-200 p-5 shadow-sm">
            <h3 className="font-semibold text-slate-900 mb-2">下一步素材</h3>
            <p className="text-sm text-slate-500 leading-6 mb-3">点击“作为下一步素材”后，AI 会基于这里的内容继续生成。</p>
            <textarea
              value={material}
              onChange={event => setMaterial(event.target.value)}
              rows={10}
              placeholder="这里会保存上一轮回复，也可以手动粘贴素材。"
              className="w-full resize-y rounded-xl border border-slate-200 px-3 py-2 text-sm leading-6 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </section>

          <section className="bg-gradient-to-br from-blue-600 to-slate-950 text-white rounded-2xl p-6 shadow-lg">
            <h3 className="text-xl font-bold mb-3">推荐流程</h3>
            <p className="text-blue-50 text-sm leading-7 mb-5">
              先完善「我的专属 Skill」，再输入需求。生成选题后作为素材，再生成大纲；大纲确定后生成正文，最后送去排版。
            </p>
            <button type="button" onClick={sendToWechat} className="inline-flex w-full items-center justify-center gap-2 bg-white text-blue-700 px-4 py-3 rounded-xl font-semibold hover:bg-blue-50">
              去公众号排版 <ArrowRight className="w-4 h-4" />
            </button>
          </section>

          <section className="bg-white rounded-2xl border border-slate-200 p-5 shadow-sm">
            <h3 className="font-semibold text-slate-900 mb-2">Skill 摘要</h3>
            <pre className="max-h-56 overflow-auto whitespace-pre-wrap rounded-xl bg-slate-50 p-3 text-xs leading-5 text-slate-500">{skillPreview.slice(0, 1200)}...</pre>
          </section>
        </aside>
      </div>
    </div>
  );
}
